'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const repo='https://github.com/X-lab2017/AIOS101';
const STORE='aios101.learning.v2', OLD_STORE='aios101.learning.v1', PREFS='aios101.preferences.v1';
let data=null,state=LearningCore.empty(),lang='zh',theme='light',fontSize=18,focusMode=false,storageOK=true,readError=false,observer=null,currentSection='',mapQuery='',mapPart=-1,pendingImport=null,importBackup=null;
const definitions=LearningData.activities;
try{const prefs=JSON.parse(localStorage.getItem(PREFS)||'{}');lang=prefs.lang==='en'?'en':'zh';theme=prefs.theme==='dark'?'dark':'light';fontSize=[16,18,20,22].includes(prefs.fontSize)?prefs.fontSize:18;const raw=localStorage.getItem(STORE)||localStorage.getItem(OLD_STORE);if(raw)state=LearningCore.validate(JSON.parse(raw),definitions);}catch{storageOK=false;readError=true;}
try{const prior=localStorage.getItem(STORE+'.before-import');if(prior)importBackup=LearningCore.validate(JSON.parse(prior),definitions);}catch{}
