const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.arrow}</svg>`;
const parts=[['认识开源','智能时代的共同创造','Discover openness','Creating together'],['理解 AI','从模型黑盒到开放系统','Understand AI','From data to systems'],['探究证据','开放程度、可复现性与生态影响','Investigate evidence','Build careful judgments'],['共同创造','从开放参与到负责任发布','Create together','Make something useful']];
const link=(path,label,style='primary')=>`<a class="btn ${style}" href="#/${path}">${label}${icon('arrow')}</a>`;
const badge=(zh,en)=>`<span class="pill"><span class="dot"></span>${T(zh,en)}</span>`;
const pageHead=(eyebrow,title,sub,extra='')=>`<div class="page-head"><div class="eyebrow">${eyebrow}</div>${extra}<h1>${title}</h1><p>${sub}</p></div>`;
const fixed=path=>`${repo}/blob/${data.sourceCommit}/${path}`;
const titleOf=u=>LearningData.units[u]?.short||(/^CH\d\d$/.test(u)?'第 '+Number(u.slice(2))+' 章':u);
const labelOf=u=>T(titleOf(u),LearningData.units[u]?.en||data.units[u]?.title||u);
const time=d=>d?new Date(d).toLocaleString(lang==='zh'?'zh-CN':'en-GB',{dateStyle:'short',timeStyle:'short'}):T('尚无保存记录','No saved work');
const getRead=u=>state.reading[u]||(state.reading[u]={done:[],bookmark:'',legacyRead:false,updatedAt:null});
const actualDone=u=>{const valid=new Set(data.units[u].sections.map(s=>s.id));return getRead(u).done.filter(id=>valid.has(id));};
const progress=u=>Math.round(actualDone(u).length/data.units[u].sections.length*100);
const getExplore=id=>state.explorations[id]||(state.explorations[id]={index:0,decision:'',explanation:'',revision:'',updatedAt:null});
const recordCount=()=>Object.values(state.notes).filter(n=>n.text.trim()).length+Object.values(state.activities).filter(a=>Object.values(a.fields).some(Boolean)).length+(state.start.question?1:0);
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function persist(quiet=true){state.updatedAt=new Date().toISOString();try{if(readError)throw Error('Unread existing data');localStorage.setItem(STORE,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}const save=$('#save-status');if(save)save.textContent=storageOK?T('已自动保存在本浏览器','Saved in this browser'):T('暂存于会话，请导出备份','Session only. Export a backup.');if(!quiet)toast(storageOK?T('已保存，可随时回来继续','Saved. You can continue later.'):T('本机保存不可用，请导出备份','Storage unavailable. Export a backup.'));}
function prefs(){try{localStorage.setItem(PREFS,JSON.stringify({lang,theme,fontSize}));}catch{}}
function shell(){
  document.documentElement.dataset.theme=theme;document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.documentElement.style.setProperty('--reading-size',fontSize+'px');
  $$('.theme-logo').forEach(i=>i.src=`assets/course/logo-${theme}.svg`);
  $('#producer-label').innerHTML=`<span>${T('课程出品方','A COURSE BY')}</span><img src="assets/logo-${theme}.svg" width="90" height="30" alt="X-lab AI">`;
  const r=(location.hash||'#/').slice(2);const nav=[['','学习首页','Home'],['map','课程地图','Course map'],['workshop','探究工坊','Workshop'],['notebook','学习手账','Notebook']];
  $('#nav').innerHTML=nav.map(([path,zh,en])=>`<a href="#/${path}" ${path?r.startsWith(path)?'aria-current="page"':'':r===''?'aria-current="page"':''}>${T(zh,en)}</a>`).join('');
  $('#lang').textContent=lang==='zh'?'EN':'中';$('#lang').ariaLabel=T('Switch to English','切换到中文');$('#theme').innerHTML=icon(theme==='light'?'moon':'sun');$('#theme').ariaLabel=T(theme==='light'?'切换深色主题':'切换浅色主题',theme==='light'?'Switch to dark theme':'Switch to light theme');$('#menu').innerHTML=icon('menu');
  $('#footer').innerHTML=`<div class="wrap learning-footer"><div><img src="assets/logo-${theme}.svg" width="108" height="36" alt="X-lab AI"><p>${T('以开源的方式学习 AI，<br>以创造的方式理解开源。','Learn AI in the open.<br>Understand by creating.')}</p></div><div class="footer-links"><a href="#/learn/APP-A">${T('仓库阅读指南','Repository reading guide')}</a><a href="#/resources">${T('术语、来源与版本','Glossary, sources & versions')}</a><a href="#/identity">${T('课程视觉基线','Course identity')}</a><a href="${repo}" target="_blank" rel="noopener">GitHub ${icon('external',13)}</a></div><div class="footer-edition">OPEN FOLIO / AIOS101<br><span>${T('交互学习打样 v0.4 · 内容持续更新','Learning preview v0.4 · Growing with the textbook')}</span><small>${T('个人记录仅保存在当前浏览器','Your work stays in this browser')}</small></div></div>`;
}
function home(){
 const resumeId=state.lastRoute.split('/')[2]?.split('?')[0];const resume=(data.units[resumeId]||definitions.some(a=>a.id===resumeId))?state.lastRoute:'#/learn/PREFACE';
 const hasWork=recordCount()>0||Object.values(state.reading).some(r=>r.done.length);
 return `<div class="wrap learner-home"><div class="edition-strip"><span><i></i>${T('教材配套 · 交互式学习资源','THE TEXTBOOK, OPENED UP')}</span><a href="#/resources">${T('绪论 + 前两章现已开放','Preface + first two chapters available')}${icon('arrow',15)}</a></div>
 <section class="learning-hero"><div class="hero-words"><div class="eyebrow">LEARN IN THE OPEN.</div><h1>${T('把一次好奇，<br>变成自己的<span>理解与创造。</span>','Turn curiosity<br>into <span>understanding.</span>')}</h1><p>${T('打开一本书，也打开 AI 背后的世界。<br>沿着真实材料探究，留下可以回看、修订和分享的学习成果。','Open the book. Look behind the answer.<br>Explore real materials and keep work you can revisit, revise and share.')}</p><div class="hero-actions"><a class="btn primary" href="${esc(resume)}">${T(hasWork?'继续我的学习':'从绪论开始',hasWork?'Continue learning':'Start with the preface')}${icon('arrow')}</a><a class="quiet-link" href="#/workshop">${T('先动手试一试','Try an exploration')}${icon('chevron',14)}</a></div><div class="entry-facts"><span>${icon('check',14)}${T('无需编程基础','No coding required')}</span><span>${icon('check',14)}${T('无需注册','No account needed')}</span><span>${icon('check',14)}${T('按自己的节奏','At your own pace')}</span></div></div>
 <div class="learning-art"><div class="art-topline"><span>OPEN FOLIO</span><span>FIELD NOTES / 001</span></div><div class="art-question"><span class="coral-square"></span>${T('我看到的是答案，<br>还是整个系统？','An answer.<br>Or a whole system?')}</div><img src="assets/course/hero-folio.svg" alt="${T('展开的书页：让问题通向开放材料','Open pages connecting questions with materials')}" width="1200" height="900"><div class="art-path"><span>01 ${T('提出问题','QUESTION')}</span><span>02 ${T('寻找证据','EVIDENCE')}</span><span>03 ${T('留下创造','CREATE')}</span></div><div class="art-stamp">AI<span>OS</span>101</div></div></section>
 <section class="continue-strip"><div class="continue-icon">${icon('bookmark',24)}</div><div><strong>${T(hasWork?'让每一步都留下痕迹':'你的第一张学习手账，从一个问题开始',hasWork?'Every step leaves a trace':'Your notebook begins with one question')}</strong><p>${T('阅读进度、问题和练习自动保存在本浏览器；可导出带走。','Reading, questions and drafts save in this browser. Export them anytime.')}</p></div><a href="#/notebook">${recordCount()} ${T('份记录','records')}${icon('arrow')}</a></section>
 <section class="learning-section"><div class="section-head"><div><div class="eyebrow">YOUR FIRST THREE STOPS</div><h2>${T('从这里，走进开放的世界。','Your first steps into an open world.')}</h2></div><p>${T('先读懂，再动手。<br>每个单元都有自己的问题与学习产物。','Read, explore, reflect.<br>Each unit gives your curiosity a direction.')}</p></div><div class="unit-grid">${['PREFACE','CH01','CH02'].map(unitCard).join('')}</div></section>
 <section class="workshop-invite"><div><span class="eyebrow">LESS WATCHING. MORE FINDING.</span><h2>${T('不急着相信。<br>先把材料打开。','Before you believe it,<br>open the materials.')}</h2><p>${T('一份模型 README 能证明什么？一条 Issue 与一个已合并 PR，又有什么不同？','What can a model README tell us? How do an open issue and a merged pull request differ?')}</p>${link('explore/materials',T('进入材料侦探台','Explore the evidence'))}</div><div class="evidence-teaser"><div class="teaser-file"><span>README.md</span><b>DeepSeek-R1</b><p>${T('模型下载 · 运行说明 · 许可','Downloads · Instructions · License')}</p></div><div class="teaser-note">${icon('search',26)}<span>${T('有材料 ≠ 有全部答案','Materials ≠ every answer')}</span></div><div class="teaser-footer"><span>${T('真实材料 / 固定版本','REAL MATERIALS / PINNED VERSION')}</span><code>0cf7856</code></div></div></section>
 <section class="learning-section course-horizon"><div><div class="eyebrow">A LONGER JOURNEY</div><h2>${T('四篇十二章，<br>一条走向创造的路。','Four parts.<br>A path to creation.')}</h2><a class="quiet-link" href="#/map">${T('展开完整课程地图','Open the full course map')}${icon('arrow')}</a></div><ol>${parts.map((p,i)=>`<li><span>0${i+1}</span><div><strong>${T(p[0],p[2])}</strong><small>${T(p[1],p[3])}</small></div><span class="horizon-state">${i===0?T('正在展开','IN PROGRESS'):T('陆续上线','COMING LATER')}</span></li>`).join('')}</ol></section></div>`;
}
function unitCard(id){const m=LearningData.units[id],u=data.units[id];return `<article class="unit-card unit-${id.toLowerCase()}"><div class="unit-card-top"><span>${m.order}</span><span>${T(m.tag,m.en)}</span>${icon(id==='CH02'?'layers':id==='CH01'?'search':'book',23)}</div><a href="#/learn/${id}"><div class="unit-card-label">${T(m.short,id==='PREFACE'?'PREFACE':id)}</div><h3>${T(m.headline,m.en)}</h3><p>${T(m.summary,'Read the Chinese textbook, explore its materials and keep your own evidence.')}</p></a><div class="unit-card-meta"><span>${T('阅读约','~')}${u.minutes}${T(' 分钟',' min reading')}</span><span>${T('配套探究','Guided exploration')}</span></div><div class="unit-card-bottom"><span>${progress(id)}% ${T('已标记阅读','marked read')}</span><a href="#/learn/${id}" aria-label="${T('进入','Open ')}${esc(m.short)}">${icon('arrow',22)}</a></div><div class="card-progress"><i style="width:${progress(id)}%"></i></div></article>`;}
function mapPage(){return `<div class="wrap learning-section">${pageHead('THE COURSE AT A GLANCE',T('找到你的下一个问题。','Find your next question.'),T('四篇十二章。已接入 '+data.chapters.filter(c=>c.status==='available').length+' 章完整正文，配套活动按制作进度开放。','Four parts, twelve chapters. '+data.chapters.filter(c=>c.status==='available').length+' chapters are readable; activities follow as they are developed.'))}<div class="catalog-tools"><label class="search-box">${icon('search')}<input id="course-search" type="search" value="${esc(mapQuery)}" placeholder="${T('搜索章节、概念或正文…','Search chapters and Chinese text…')}" aria-label="${T('搜索课程','Search course')}"></label><div class="filter-row">${[['-1','全部','All'],...parts.map((p,i)=>[String(i),p[0],p[2]])].map(([i,zh,en])=>`<button class="filter ${mapPart===Number(i)?'active':''}" data-part="${i}" aria-pressed="${mapPart===Number(i)}">${T(zh,en)}</button>`).join('')}</div></div><div id="catalog-results">${catalogResults()}</div></div>`;}
function catalogResults(){const query=mapQuery.trim().toLowerCase();let html='';if(!query&&mapPart<0)html+=`<a class="preface-banner" href="#/learn/PREFACE"><span>00 / ${T('从这里开始','START HERE')}</span><strong>${T('绪论：从一次提问，看见一个开放的世界','Preface: a question opens a world')}</strong>${icon('arrow')}</a>`;
 const chapters=data.chapters.filter(c=>(mapPart<0||c.part===mapPart)&&(!query||[c.title,c.en,c.id,c.question,data.units[c.id]?.markdown||''].join(' ').toLowerCase().includes(query)));
 html+=chapters.map(c=>`<article class="catalog-row"><div class="chapter-num">${c.id.slice(2)}</div><div><span class="chapter-part">${T(parts[c.part][0],parts[c.part][2])} · ${c.outcomes}</span><h2>${esc(T(c.title,c.en))}</h2><p>${esc(c.question)}</p>${query&&data.units[c.id]?`<div class="search-snippet">${esc(searchSnippet(data.units[c.id].markdown,query))}</div>`:''}</div><div class="catalog-action">${c.status==='available'?`<span class="status-live">${definitions.some(a=>a.unit===c.id)?T('完整阅读 + 探究','Read + explore'):T('正文草稿 · 活动待制作','Draft reading · activities to come')}</span>${link('learn/'+c.id,T('开始学习','Open lesson'),'secondary')}`:`<span class="status-planned">${T('内容待上线','Coming later')}</span><details><summary>${T('学习目标','Learning goal')}</summary><p>${esc(c.evidence)}</p></details>`}</div></article>`).join('');if(!chapters.length)html+=`<div class="empty-state"><h2>${T('暂时没有匹配内容','No matching chapters')}</h2><p>${T('试试“模型”“复用”或章节编号。','Try a chapter ID or a Chinese term such as 模型.')}</p></div>`;return html;}
function searchSnippet(raw,q){const clean=raw.replace(/[#>*`|\[\]]/g,' ');const at=clean.toLowerCase().indexOf(q);return at<0?'':(at>35?'…':'')+clean.slice(Math.max(0,at-35),at+95)+'…';}
function reader(id,params){const u=data.units[id];if(!u)return unavailable(id);const meta=LearningData.units[id]||{short:id,en:u.title};const read=getRead(id);const selected=u.sections.find(s=>s.id===params.get('section'))||u.sections.find(s=>s.id===read.bookmark)||u.sections[0];currentSection=selected.id;
 const toc=u.sections.map((s,i)=>`<a href="#/learn/${id}?section=${s.id}" data-section-link="${s.id}" ${s.id===selected.id?'aria-current="location"':''}><span>${read.done.includes(s.id)?'✓':String(i+1).padStart(2,'0')}</span>${esc(s.title)}</a>`).join('');
 return `<div class="reader-shell ${focusMode?'is-focused':''}"><div class="reader-top wrap"><a href="#/map" class="quiet-link">← ${T('课程地图','Course map')}</a><div class="reader-tools"><button id="font-down" class="tool-button" aria-label="${T('减小字号','Decrease font size')}">A−</button><span>${fontSize}</span><button id="font-up" class="tool-button" aria-label="${T('增大字号','Increase font size')}">A+</button><button id="focus-mode" class="tool-button" aria-pressed="${focusMode}">${T(focusMode?'退出专注':'专注阅读',focusMode?'Exit focus':'Focus')}</button><a class="tool-button" href="resources/${id}.md" download>${icon('download',16)} Markdown</a></div></div>
 <div class="reading-layout"><aside class="reading-sidebar"><label class="chapter-switch-label" for="chapter-switch">${T('正在阅读','READING')}</label><select id="chapter-switch">${Object.entries(data.units).map(([key,v])=>`<option value="${key}" ${key===id?'selected':''}>${esc(titleOf(key)+' · '+v.title.replace(/^第 \d 章\s*/,''))}</option>`).join('')}</select><div class="reading-progress"><span>${actualDone(id).length} / ${u.sections.length} ${T('节已标记','sections marked')}</span><div><i style="width:${progress(id)}%"></i></div></div><nav class="reader-toc" aria-label="${T('本章目录','Chapter contents')}">${toc}</nav>${meta.explorer?`<a class="sidebar-explore" href="#/explore/${meta.explorer}">${icon('layers')}${T('打开本章探究','Explore this chapter')}${icon('arrow',15)}</a>`:''}</aside>
 <div class="reading-center"><header class="reading-heading"><div class="eyebrow">${esc(id)} / ${T('阅读与理解','READ & UNDERSTAND')}</div><h1>${esc(u.title)}</h1><div class="reading-meta"><span>${esc(u.version)} · ${esc(u.status)}</span><span>${T('阅读估计','Reading estimate')} ${u.minutes} ${T('分钟','min')}</span></div>${lang==='en'?'<p class="translation-note">The textbook and worksheets are in Chinese. English translations have not yet been reviewed.</p>':''}<details class="mobile-toc"><summary>${T('展开本章目录','Chapter contents')}</summary><nav>${toc}</nav></details></header>
 <article class="book-content">${u.sections.map((s,i)=>`<section class="reading-section" id="${s.id}" data-reading-section="${s.id}"><div class="reading-section-number">${String(i+1).padStart(2,'0')} / ${u.sections.length}</div><h2>${esc(s.title)}</h2>${s.html}<div class="section-actions"><button class="read-mark ${read.done.includes(s.id)?'marked':''}" data-mark="${s.id}" aria-pressed="${read.done.includes(s.id)}">${icon('check',15)}${T(read.done.includes(s.id)?'我已读过 · 撤销':'标记我已读过',read.done.includes(s.id)?'Read · undo':'Mark as read')}</button><button class="note-trigger" data-note="${s.id}">${icon('note',15)}${T('记下一个想法','Add a note')}</button></div></section>`).join('')}</article>
 <section class="after-reading"><div class="eyebrow">NOW, MAKE IT YOURS.</div><h2>${T('读到这里，带着问题动手。','Now put your questions to work.')}</h2>${id==='PREFACE'?startingPoint():id==='APP-A'?`<p>${T('回到具体材料，练习定位对象与版本。','Return to a case and locate its materials and version.')}</p>${link('explore/materials',T('观察 DeepSeek-R1 材料','Explore DeepSeek-R1'))}`:`<div class="reader-activities">${definitions.filter(a=>a.unit===id).map(activityCard).join('')||`<p class="muted">${T('本章配套活动正在制作。可以先阅读章末问题，将自己的疑问记入页边手账。','Activities for this chapter are being developed. Read the chapter questions and keep your own notes.')}</p>`}</div>`}</section>
 <div class="source-trail"><p>${T('正文来自教材正本；阅读标记仅记录个人进度。','The canonical textbook, unchanged. Read marks track your own progress.')}</p><a href="${fixed(u.sourcePath)}" target="_blank" rel="noopener">${T('核对原文与版本','Inspect the source')} · ${data.sourceCommit.slice(0,7)} ${icon('external',13)}</a><a href="#/resources">${T('查看来源登记','Source register')}</a></div>${id==='PREFACE'?link('learn/CH01',T('继续第一章','Continue to Chapter 1')):id==='CH01'?link('learn/CH02',T('继续第二章','Continue to Chapter 2')):id==='CH02'&&data.units.CH03?link('learn/CH03',T('继续第三章草稿','Continue to Chapter 3 draft')):''}</div>
 <aside class="reading-notes" id="reading-notes">${notePanel(id,selected.id)}</aside></div></div>`;
}
function notePanel(id,section){const sec=data.units[id].sections.find(s=>s.id===section);const key=id+'__'+section,note=state.notes[key];return `<div class="note-panel"><div class="note-panel-title">${icon('note',20)}<strong>${T('页边手账','Margin notes')}</strong></div><p class="note-anchor">${esc(sec.title)}</p><label for="margin-note">${T('一个疑问、一条证据，或一个反例','A question, a piece of evidence, or a counterexample')}</label><textarea id="margin-note" data-note-key="${key}" maxlength="6000" placeholder="${T('用自己的话，留下一个想法…','Leave a thought in your own words…')}">${esc(note?.text||'')}</textarea><p id="save-status" class="save-status" role="status">${T('只保存在本浏览器','Saved only in this browser')}</p>${note?.digest&&note.digest!==data.units[id].digest?`<p class="note-warning">${T('这条笔记来自较早正文，请对照新版本回看。','This note refers to an earlier text. Revisit it against this version.')}</p>`:''}<button class="btn secondary full" id="save-bookmark" data-unit="${id}" data-section="${section}">${icon('bookmark',16)}${T('下次从这里继续','Resume here next time')}</button><a href="#/notebook" class="quiet-link">${T('查看全部手账','All your notes')}${icon('arrow',14)}</a></div><div class="reading-tip"><span>${T('阅读小提示','READING TIP')}</span><p>${T('读到“因此”时，停一下：前面的材料真的支持这个结论吗？','Pause at “therefore”: does the evidence actually support the conclusion?')}</p></div>`;}
function startingPoint(){return `<form id="start-form" class="start-form"><p>${T('不需要标准答案。以后再回来，看看自己的问题怎样改变。','No model answer needed. Return later to see how your questions changed.')}</p>${[['product','我最近使用或关注的 AI 成果','An AI tool or work I care about'],['question','我最想打开的黑盒','The question I want to explore'],['contribution','我愿意尝试的一种贡献','A contribution I could try']].map(([key,zh,en])=>`<label>${T(zh,en)}<textarea name="${key}" maxlength="6000" rows="2">${esc(state.start[key])}</textarea></label>`).join('')}<div class="form-bottom"><span class="save-status" id="save-status" role="status">${T('边写边保存，仅在本机','Autosaved on this device')}</span><button class="btn primary" type="submit">${T('保存我的起点','Save my starting point')}${icon('check')}</button></div></form>`;}
function unavailable(id){return `<div class="wrap empty-state"><h1>${T('这一章正在生长','This chapter is still growing')}</h1><p>${T('先从已经开放的绪论和前两章开始吧。','Start with the preface and the first two chapters.')}</p>${link('map',T('返回课程地图','Back to the course map'))}</div>`;}
function activityCard(a){const r=state.activities[a.id];const filled=r?LearningCore.fieldsOf(a).filter(f=>(r.fields[f.id]||'').trim()).length:0;return `<a class="activity-card" href="#/activity/${a.id}"><span class="activity-card-id">${a.id} ${a.simulated?'· '+T('模拟活动','SIMULATION'):''}</span><h3>${esc(T(a.title,a.en))}</h3><p>${esc(T(a.summary,a.deliverable))}</p><div><span>${a.minutes} ${T('分钟 · 设计估计','min · estimate')}</span><strong>${filled?T('继续草稿','Continue draft'):T('开始探究','Begin')}${icon('arrow',15)}</strong></div></a>`;}
function workshop(){return `<div class="wrap learning-section">${pageHead('LEARNING BY INVESTIGATING',T('把理解，放进一次行动。','Make understanding an action.'),T('先在观察窗里辨认证据，再完成自己的学习产物。所有核心活动无需编程或外部账号。','Explore evidence, then make your own learning artifact. No coding or external accounts required.'))}<div class="explore-cards">${[['system','00','展开一次回答','Unfold an answer','五个观察层，看见界面背后的系统。'],['materials','01','材料侦探台','The evidence desk','读懂 DeepSeek-R1 材料能说什么、不能说什么。'],['collaboration','02','协作观察窗','A window into collaboration','对读一个真实 Issue 与一个已合并 PR。']].map(([id,n,zh,en,p])=>`<a href="#/explore/${id}" class="explore-card"><span class="explore-number">${n}</span>${icon(id==='system'?'layers':id==='materials'?'search':'note',28)}<h2>${T(zh,en)}</h2><p>${T(p,'Observe, make a judgment, then inspect the explanation.')}</p><span>${T('概念与案例探索','Concept & case exploration')}${icon('arrow')}</span></a>`).join('')}</div><div class="section-head"><div><div class="eyebrow">MAKE YOUR OWN EVIDENCE</div><h2>${T('四项活动，四份自己的成果。','Four activities. Your own evidence.')}</h2></div><p>${T('随时保存草稿。记录反馈，<br>保留修订，再导出带走。','Save drafts. Record feedback.<br>Keep revisions and take your work with you.')}</p></div><div class="activity-grid">${definitions.map(activityCard).join('')}</div></div>`;}
function exploration(id){
 if(!['system','materials','collaboration'].includes(id))return unavailable(id);
 const x=getExplore(id),unit=id==='system'?'PREFACE':id==='materials'?'CH01':'CH02';
 const info={system:['展开一次回答','Unfold an answer','看见一个答案背后的五个观察层。它们是学习支架，不是某个产品的实测架构。','Five observation layers: a learning aid, not a measured product architecture.'],materials:['材料侦探台','The evidence desk','把对象、材料与结论放在一起看。先打开一张卡片，再检查它能够支持什么。','Match objects, materials and claims. Open a card, then inspect what it supports.'],collaboration:['协作观察窗','A window into collaboration','一个 Issue 与一个 PR：两条独立的真实记录，帮助区分问题、变更和项目决定。','An issue and a pull request: two independent records of questions, changes and decisions.']}[id];
 const cards=id==='system'?LearningData.system:id==='materials'?LearningData.materials:[['Issue #386','Issue #386'],['PR #364','Pull request #364']];const active=Math.min(x.index,cards.length-1);
 return `<div class="wrap learning-section exploration-page"><a class="quiet-link" href="#/learn/${unit}">← ${T('返回','Back to ')}${labelOf(unit)}</a>${pageHead('OPEN THE MATERIALS / '+unit,T(info[0],info[1]),T(info[2],info[3]))}<div class="exploration-board ${id}"><div class="exploration-selector" role="group" aria-label="${T('选择观察材料','Choose material')}">${cards.map((c,i)=>`<button class="explore-option ${i===active?'selected':''}" data-explore-id="${id}" data-explore-index="${i}" aria-pressed="${i===active}"><span>${String(i+1).padStart(2,'0')}</span><strong>${T(c[0],c[1])}</strong>${icon('arrow',16)}</button>`).join('')}</div><div id="exploration-detail" class="exploration-detail">${explorationDetail(id,active)}</div></div><section class="judgment-lab"><div><div class="eyebrow">PAUSE. WHAT CAN WE CLAIM?</div><h2>${T('先作判断，再查看解释。','Make a judgment. Then investigate.')}</h2><p>${T('这是证据辨析练习，不计分。请用一句话说明你的依据。','This is an ungraded evidence exercise. Explain your reasoning in a sentence.')}</p></div><form id="exploration-form" data-exploration="${id}"><fieldset><legend>${esc(explorationClaim(id))}</legend><div class="choice-grid">${[['supported','材料支持','Supported'],['unknown','仍需核查','Needs more evidence'],['overreach','过度推断','Overreaching']].map(([v,zh,en])=>`<label><input type="radio" name="decision" value="${v}" ${x.decision===v?'checked':''}><span>${T(zh,en)}</span></label>`).join('')}</div></fieldset><label class="field">${T('我的依据','My reasoning')}<textarea name="explanation" maxlength="6000" rows="3">${esc(x.explanation)}</textarea></label><button type="button" class="btn primary" id="reveal-explanation">${T('对照材料中的解释','Compare with the explanation')}${icon('arrow')}</button><div id="exploration-feedback" class="feedback-panel hidden" role="status">${explorationFeedback(id)}</div><label class="field revision-field">${T('我想修订或补充的地方','What I would revise or add')}<textarea name="revision" maxlength="6000" rows="3">${esc(x.revision)}</textarea></label><div class="form-bottom"><span id="save-status" class="save-status">${T('观察与解释仅保存在本机','Observations stay on this device')}</span><button type="submit" class="btn secondary">${T('保存观察记录','Save observation')}${icon('check')}</button></div></form></section><div class="next-exploration">${link(id==='system'?'learn/PREFACE?section='+data.units.PREFACE.sections.at(-1).id:'activity/'+(id==='materials'?'ACT-CH01-01':'ACT-CH02-01'),T('把观察带进自己的活动','Take this into your own work'))}</div></div>`;
}
function explorationDetail(id,index){
 if(id==='system'){const c=LearningData.system[index];return `<span class="detail-tag">LAYER 0${index+1} / 05</span><div class="layer-stack" aria-hidden="true">${[4,3,2,1,0].map(i=>`<i class="${i===index?'lit':''}" style="--layer:${i}"></i>`).join('')}</div><h2>${T(c[0],c[1])}</h2><p class="detail-lead">${esc(c[2])}</p><div class="evidence-line"><span>${T('可以观察','LOOK FOR')}</span><p>${esc(c[3])}</p></div><div class="evidence-line"><span>${T('继续追问','ASK NEXT')}</span><p>${esc(c[4])}</p></div><p class="small-note">${T('概念示意 · 各层在实际系统中可能交叉','Conceptual model · Layers can overlap in real systems')}</p>`;}
 if(id==='materials'){const c=LearningData.materials[index];return `<div class="file-tab">${icon('book',16)} deepseek-ai / DeepSeek-R1 <code>0cf7856</code></div><span class="detail-tag">EVIDENCE ${String(index+1).padStart(2,'0')} / 06</span><h2>${T(c[0],c[1])}</h2><p class="detail-lead">${esc(c[2])}</p><div class="claim-pair"><div><span>${icon('check',17)}${T('材料支持','WHAT IT SUPPORTS')}</span><p>${esc(c[3])}</p></div><div><span>${icon('search',17)}${T('仍需保留的边界','THE LIMIT')}</span><p>${esc(c[4])}</p></div></div><a href="https://github.com/deepseek-ai/DeepSeek-R1/blob/0cf78561f1d51c84a21b2190626b21116d5c68bb/README.md" target="_blank" rel="noopener" class="quiet-link">${T('核对固定原文','Inspect the pinned source')} · ${c[5]} ${icon('external',14)}</a><p class="small-note">${T('根据第一章整理的材料导航，不是项目开放度认证。','A guide derived from Chapter 1, not an openness certification.')}</p>`;}
 const isPR=index===1;return `<div class="file-tab">${icon('note',16)} Infrasys-AI / AIInfra <span class="record-status ${isPR?'merged':''}">${isPR?T('已合并 · 历史记录','Merged · historical'):T('开放 · 读取时状态','Open · at reading date')}</span></div><span class="detail-tag">${isPR?'PULL REQUEST #364':'ISSUE #386'}</span><h2>${isPR?T('一个可检查的文档修正','A reviewable documentation correction'):T('一个有位置和来源的问题报告','A question with a location and a source')}</h2><p class="detail-lead">${isPR?T('贡献者提出修改量化章节中的字节数表述。维护者于 2025-12-22 合并，提交为 b97c038。','A contributor proposed a byte-size correction in the quantization chapter. It was merged on 2025-12-22 as b97c038.'):T('报告者于 2026-05-13 对 H100 FP8 峰值算力表述提出疑问，并附项目位置与官方文档链接。','On 2026-05-13, a reporter questioned an H100 FP8 figure and linked the project location and official documentation.')}</p><div class="record-timeline"><span>${isPR?'2025-12-04':'2026-05-13'}<b>${T(isPR?'提出变更':'提出问题',isPR?'Proposed':'Reported')}</b></span><i></i><span>${isPR?'2025-12-22':'2026-10-28'}<b>${T(isPR?'项目合并':'读取时仍开放',isPR?'Merged':'Still open when read')}</b></span></div><div class="claim-pair"><div><span>${T('可以观察','OBSERVABLE')}</span><p>${T(isPR?'具体变更进入了目标项目。':'问题进入了公开跟踪过程。',isPR?'The project accepted this particular change.':'The question entered a public tracking process.')}</p></div><div><span>${T('不能据此推出','NOT ESTABLISHED')}</span><p>${T(isPR?'项目所有内容均准确，或每次贡献都会被接纳。':'报告者技术判断全部成立，或问题已经修复。',isPR?'That all content is accurate or every contribution will be accepted.':'That every technical claim is correct, or the issue has been fixed.')}</p></div></div><a class="quiet-link" href="https://github.com/Infrasys-AI/AIInfra/${isPR?'pull/364':'issues/386'}" target="_blank" rel="noopener">${T('查看原始记录','Open the original record')}${icon('external',14)}</a><p class="small-note">${T('教材读取日：2026-10-28。两条记录互相独立；它们不构成同一条修复链。','Textbook reading date: 2026-10-28. These are independent records, not one repair sequence.')}</p>`;
}
function explorationClaim(id){return id==='system'?T('两个项目有共享贡献者，所以它们存在软件依赖。','Two projects share contributors, so one must depend on the other.'):id==='materials'?T('README 提供模型权重下载入口，所以整个训练过程已经可以复现。','The README links to model weights, so the whole training process is reproducible.'):T('PR #364 的合并记录，支持“项目接受了这项具体变更”。','The merge record for PR #364 supports the claim that the project accepted this particular change.');}
function explorationFeedback(id){return `<strong>${id==='collaboration'?T('这项有限结论有记录支持。','This limited claim is supported.'):T('这一步推断超过了材料。','This inference goes beyond the evidence.')}</strong><p>${id==='system'?T('共享贡献者是人员关系，软件依赖需要依赖声明或运行材料来核查。记录关系与推断关系应分开。','Shared contributors describe a people relationship. Dependency claims need dependency declarations or runtime evidence.'):id==='materials'?T('权重获取只回答一类材料在哪里。训练复现还需要明确目标、代码、数据信息、配置与资源条件，不能由下载入口单独证明。','A download link identifies one material. Training reproducibility additionally depends on the goal, code, data information, configuration and resources.'):T('合并记录说明这一组变更被接纳。它不证明整个项目质量，也不证明实际公共价值；后者还需要使用、受益、成本与风险证据。','A merge records acceptance of this change. It establishes neither the quality of the whole project nor its public value.')}</p><a href="#/learn/${id==='system'?'PREFACE':id==='materials'?'CH01':'CH02'}">${T('回到教材重新阅读','Return to the textbook')}</a>`;}
function releaseWidget(){const active=Math.min(getExplore('releases').index,3);return `<div class="release-widget"><div class="release-widget-heading"><span>${T('虚构案例 · 四次发布观察器','FICTIONAL CASE · FOUR RELEASES')}</span><small>${T('点击展开新增条件','Open the added conditions')}</small></div><div class="release-tabs">${LearningData.releases.map((r,i)=>`<button data-release="${i}" aria-pressed="${i===active}" class="${i===active?'active':''}">${i+1}<span>${T(r.title,r.tag.split('/')[1])}</span></button>`).join('')}</div><div id="release-content">${releaseDetail(active)}</div></div>`;}
function releaseDetail(i){const r=LearningData.releases[i];return `<h3>${T(r.title,r.tag)}</h3><p>${T(r.body,r.en)}</p><div class="release-boundary">${icon('search',16)}${esc(r.hint)}</div>`;}
function activityPage(id,params){const a=definitions.find(d=>d.id===id);if(!a)return unavailable(id);const r=LearningCore.activity(state,id);const requested=Number(params.get('step'));if(params.has('step')&&Number.isInteger(requested)&&requested>=0&&requested<a.steps.length)r.step=requested;const step=a.steps[r.step],fields=LearningCore.fieldsOf(a),filled=fields.filter(f=>(r.fields[f.id]||'').trim()).length;return `<div class="wrap activity-page"><a class="quiet-link" href="#/workshop">← ${T('探究工坊','Workshop')}</a><header class="activity-heading"><div><div class="eyebrow">${a.id} / ${a.evidence}</div><h1>${T(a.title,a.en)}</h1><p>${esc(T(a.summary,a.deliverable))}</p></div><div class="activity-heading-status"><span class="pill">${a.simulated?T('模拟学习活动','SIMULATION'):T('个人探究','PERSONAL INQUIRY')}</span><small>${a.minutes} ${T('分钟 · 设计估计','min · estimate')}</small><small id="activity-count">${filled} / ${fields.length} ${T('项已填','fields filled')}</small></div></header>${lang==='en'?'<p class="translation-note">The activity prompts and canonical worksheets are in Chinese. Your answers can be in either language.</p>':''}<div class="activity-layout"><aside class="activity-sidebar"><ol class="step-list">${a.steps.map((s,i)=>`<li><a href="#/activity/${id}?step=${i}" ${r.step===i?'aria-current="step"':''}><span>${i+1}</span>${T(s.title,s.en)}</a></li>`).join('')}</ol><div class="activity-source"><p>${T('随时离开，随时继续。<br>草稿仅保存在本浏览器。','Leave and return anytime.<br>Your draft stays in this browser.')}</p><a href="resources/${id}.md" download>${icon('download',15)}${T('下载完整任务单','Download the worksheet')}</a><a href="${fixed('activities/student/'+id+'.md')}" target="_blank" rel="noopener">${T('核对教学任务单','Canonical worksheet')}${icon('external',13)}</a></div></aside><section class="activity-main"><div class="step-topline"><span>STEP ${String(r.step+1).padStart(2,'0')} / ${a.steps.length}</span><span id="save-status" role="status">${T('边写边保存','Autosave on input')}</span></div><h2>${T(step.title,step.en)}</h2><p class="step-intro">${esc(step.intro)}</p>${a.kind==='releases'&&r.step<2?releaseWidget():''}${a.kind==='analysis'&&r.step===0?`<details class="case-prompt"><summary>${T('没有使用记录？看看这个模拟情境','No personal example? See a fictional scenario')}</summary><p>课堂模拟：一位学习者让 AI 为课程报告寻找研究线索，得到一条尚未核对的文献描述。这里没有真实模型调用；你可以围绕“怎样核查来源”描述这个模拟案例，并在工具名称中注明“课堂模拟”。</p></details>`:''}${a.kind==='contribution'&&r.step===0?contributionBrief():''}<form id="activity-form" data-activity="${id}">${renderFields(step.fields,r.fields)}<div class="step-navigation">${r.step>0?link('activity/'+id+'?step='+(r.step-1),T('上一步','Previous'),'secondary'):'<span></span>'}${r.step<a.steps.length-1?link('activity/'+id+'?step='+(r.step+1),T('保存并继续','Continue')):`<button class="btn primary" id="check-completion" type="button">${T('检查填写情况','Check my fields')}${icon('check')}</button>`}</div></form><div id="completion-feedback" class="completion-feedback" role="status"></div></section><aside class="activity-output"><div class="output-card"><span class="eyebrow">YOUR LEARNING ARTIFACT</span><h3>${T('这次会留下什么？','What will you keep?')}</h3><p>${esc(a.deliverable)}</p><div class="artifact-preview" id="artifact-preview">${artifactPreview(a,r)}</div><button class="btn secondary full" id="snapshot-button" data-id="${id}">${icon('bookmark',16)}${T('保留一次修订快照','Keep a revision snapshot')}</button><button class="btn primary full" data-export-activity="${id}">${icon('download',16)}${T('导出完整 Markdown','Export Markdown')}</button><button class="quiet-link" data-preview-activity="${id}">${T('预览完整产物与历史','Preview all fields & history')}${icon('arrow',14)}</button><small>${T('填写进度不等于学习成绩。<br>不确定时，请明确写“待核查”。','Field completion is not a grade.<br>Keep uncertainties explicit.')}</small></div></aside></div></div>`;}
function renderFields(fields,values){let previous='';return fields.map(f=>{let heading='';if(f.row&&f.row!==previous){heading=`<h3 class="field-group-heading">${esc(f.row)}</h3>`;previous=f.row;}const id='field-'+f.id;return heading+`<div class="field"><label for="${id}">${esc(f.label)}</label>${f.hint?`<p id="hint-${f.id}" class="field-hint">${esc(f.hint)}</p>`:''}${f.type==='select'?`<select id="${id}" name="${f.id}"><option value="">${T('请选择','Choose')}</option>${f.options.map(v=>`<option ${values[f.id]===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`:f.type==='text'?`<input id="${id}" type="text" name="${f.id}" maxlength="12000" value="${esc(values[f.id]||'')}" ${f.hint?`aria-describedby="hint-${f.id}"`:''}>`:`<textarea id="${id}" name="${f.id}" rows="3" maxlength="12000" ${f.hint?`aria-describedby="hint-${f.id}"`:''}>${esc(values[f.id]||'')}</textarea>`}</div>`;}).join('');}
function artifactPreview(a,r){const pairs=a.kind==='map'?[['对象',r.fields.object],['问题',r.fields.core_question],['下一步',r.fields.next_action]]:a.kind==='contribution'?[['需要',r.fields.need],['交付物',r.fields.deliverable],['修订',r.fields.revised_proposal]]:a.kind==='analysis'?[['案例',r.fields.tool],['理解问题',r.fields.questions_1_question],['边界',r.fields.boundary]]:[['初判',r.fields.initial_judgment],['目标',r.fields.reuse_goal],['边界',r.fields.gap_value]];return pairs.map(([label,value])=>`<div><span>${label}</span><p>${esc(value||'…')}</p></div>`).join('');}
function contributionBrief(){return `<details class="case-prompt" open><summary>虚构项目情境与贡献规则</summary><p>校园 AI 学习助手资料包：核查指南 v1.2、学科示例集 v1.0（理工科为主）、新手评测题 v1.1，以及 README、许可、来源说明与贡献指南。</p><ul><li>帮助新生核查回答，不宣传某个 AI 产品。</li><li>一次解决一个小问题，说明来源、检查方式与 AI 使用。</li><li>可选需要：解释术语、补充文科引文案例、明确翻译范围、完善评测填写说明、补充 AI 使用披露。</li><li>不使用私人对话、真实学生作业或无权发布的材料。</li><li>模拟评审可接纳、要求修改或暂不接纳；不代表真实项目意见。</li></ul></details>`;}
function notebook(){const notes=Object.entries(state.notes).filter(([,v])=>v.text.trim());const saved=definitions.filter(a=>state.activities[a.id]&&Object.values(state.activities[a.id].fields).some(Boolean));return `<div class="wrap learning-section notebook-page">${pageHead('YOUR THINKING, IN PROGRESS',T('留下问题，也看见自己的变化。','Keep your questions.<br>See your thinking change.'),T('这里是你的个人学习手账。所有内容保存在当前浏览器，导出后可带到其他设备继续。','Your personal notebook lives in this browser. Export a backup to continue on another device.'))}<div class="notebook-toolbar"><button class="btn primary" data-export="json">${icon('download')}${T('备份全部记录','Back up everything')}</button><button class="btn secondary" id="import-button">${T('导入备份','Import backup')}</button><button class="btn secondary" id="text-backup">${T('文本备份与恢复','Text backup & restore')}</button>${importBackup?`<button class="btn secondary" id="previous-backup">${T('下载导入前备份','Download pre-import backup')}</button>`:''}<button class="tool-button" id="print-notebook">${T('打印手账','Print notebook')}</button></div><div class="notebook-stats"><div><strong>${Object.keys(data.units).filter(id=>actualDone(id).length).length}</strong><span>${T('个单元留下阅读标记','units with reading marks')}</span></div><div><strong>${notes.length}</strong><span>${T('条页边想法','margin notes')}</span></div><div><strong>${saved.length}</strong><span>${T('份活动草稿','activity drafts')}</span></div><p>${T('进度描述学习过程，<br>不代表成绩或能力认证。','Progress describes your process,<br>not a grade or certification.')}</p></div><section class="notebook-section"><div class="section-head"><h2>${T('我的起点问题','My starting point')}</h2><a href="#/learn/PREFACE?section=${data.units.PREFACE.sections.at(-1).id}">${T('回去修改','Revisit')}</a></div>${state.start.question||state.start.product?`<div class="starting-card"><span>${esc(state.start.product||T('对象待补充','Object to add'))}</span><h3>${esc(state.start.question||T('问题待补充','Question to add'))}</h3><p>${T('我愿意尝试：','I could try: ')}${esc(state.start.contribution||'…')}</p></div>`:`<div class="empty-inline">${T('还没有起点问题。给未来的自己留下一点好奇。','No starting question yet. Leave some curiosity for your future self.')}${link('learn/PREFACE?section='+data.units.PREFACE.sections.at(-1).id,T('留下第一个问题','Leave your first question'),'secondary')}</div>`}</section><section class="notebook-section"><div class="section-head"><h2>${T('我的学习产物','My learning artifacts')}</h2><a href="#/workshop">${T('选择下一项活动','Choose an activity')}${icon('arrow',14)}</a></div>${saved.length?`<div class="saved-artifacts">${saved.map(a=>{const r=state.activities[a.id];return `<article class="saved-artifact"><span>${a.id} · ${a.simulated?T('模拟','SIMULATION'):a.evidence}</span><h3>${T(a.title,a.en)}</h3><p>${LearningCore.fieldsOf(a).length-LearningCore.missing(a,r).length} ${T('项已填写','fields filled')} · ${r.history.length} ${T('次修订快照','revision snapshots')}</p><div class="saved-status">${r.status==='complete'?T('本人已检查填写 · 待教学评审','Self-checked · awaiting review'):T('草稿，可以继续','Draft · keep going')}</div><small>${time(r.updatedAt)}</small><div class="actions">${link('activity/'+a.id,T('继续修改','Continue'),'secondary')}<button class="tool-button" data-export-activity="${a.id}" aria-label="${T('导出','Export ')}${a.id}">${icon('download')}</button></div></article>`;}).join('')}</div>`:`<div class="empty-inline">${T('一份对照分析、一张问题地图，都是学习留下的证据。','An analysis or question map makes your learning visible.')}${link('workshop',T('开始一项探究','Start an inquiry'),'secondary')}</div>`}</section><section class="notebook-section"><h2>${T('页边想法','Margin notes')}</h2>${notes.length?notes.map(([key,n])=>{const [u,s]=key.split('__'),sec=data.units[u]?.sections.find(x=>x.id===s);return `<article class="saved-note"><a href="#/learn/${u}?section=${s}">${esc(titleOf(u))} / ${esc(sec?.title||T('原小节已调整','Section changed'))}${icon('arrow',14)}</a><p>${esc(n.text)}</p><small>${esc(n.version)} · ${time(n.updatedAt)}</small></article>`;}).join(''):`<p class="muted">${T('阅读时，点击“记下一个想法”，把疑问留在具体段落旁。','While reading, add a note beside a specific section.')}</p>`}</section><section class="notebook-section"><h2>${T('我的观察与修订','Observations & revisions')}</h2>${Object.entries(state.explorations).filter(([k,v])=>k!=='releases'&&(v.explanation||v.revision)).map(([id,x])=>`<article class="saved-note"><a href="#/explore/${id}">${T(id==='system'?'系统展开':id==='materials'?'材料侦探台':'协作观察窗',id)}${icon('arrow',14)}</a><p>${esc(x.explanation)}</p><blockquote>${esc(x.revision||T('尚未补充修订','No revision yet'))}</blockquote></article>`).join('')||`<p class="muted">${T('案例探究中保存的解释会出现在这里。','Explanations from your explorations will appear here.')}</p>`}</section>${state.legacy?`<details class="legacy-record"><summary>${T('上一版学习记录已保留','Previous-version records preserved')}</summary><p>${T('旧版起点已迁移；原系统探索与评审文字仍保留如下。','Your starting point was migrated. Original exploration and review text remains below.')}</p><pre>${esc(JSON.stringify(state.legacy,null,2))}</pre></details>`:''}<div class="notebook-management"><p>${T('建议定期备份。清除浏览器数据会移除本机记录。','Back up periodically. Clearing browser data removes local work.')}</p><button class="text-danger" id="clear-records">${T('清除本机学习记录','Clear this device’s learning records')}</button></div></div>`;}
function resources(){return `<div class="wrap learning-section">${pageHead('KEEP THE SOURCES WITHIN REACH',T('读不懂的词，回得去的来源。','Words explained.<br>Sources within reach.'),T('术语取自章节正文；具体材料与版本始终可以回查。','Glossary entries come from the chapters. Materials and versions stay traceable.'))}<div class="resources-top"><a class="resource-feature" href="#/learn/APP-A"><span>READING GUIDE / A</span><h2>${T('第一次打开 GitHub 仓库？','New to reading repositories?')}</h2><p>${T('先读懂 README、许可与提交号。无需安装工具。','Start with the README, license and commit ID. No installation needed.')}</p>${icon('arrow',25)}</a><div class="version-card"><span class="eyebrow">THIS EDITION</span><h3>AIOS101 · v0.4</h3><p>${T('绪论 v0.3 · CH01 / CH02 v0.4<br>数字学习打样 · 教学评审待完成','Preface v0.3 · CH01 / CH02 v0.4<br>Learning preview · Educational review pending')}</p><a href="${repo}/commit/${data.sourceCommit}" target="_blank" rel="noopener">${T('教材快照','Source snapshot')} ${data.sourceCommit.slice(0,7)} ${icon('external',13)}</a><a href="resources/source-register.md" download>${T('下载完整来源登记','Download source register')}</a><a href="resources/learning-experience-spec.md" download>${T('查看学习体验规格','Learning experience specification')}</a></div></div><label class="search-box glossary-search">${icon('search')}<input id="glossary-search" type="search" placeholder="${T('搜索术语，例如：复用、参数、Issue','Search a term: 复用, 参数, Issue')}" aria-label="${T('搜索术语','Search glossary')}"></label><div id="glossary-results" class="glossary-grid">${glossaryCards('')}</div><section class="resources-note"><h2>${T('和教材一起生长','Growing with the textbook')}</h2><p>${T('正文由仓库 Markdown 生成；新增内容会随构建更新。阅读与练习可用于打样评审，当前不颁发证书，也不自动判断学习成果。','Reading pages are generated from the repository Markdown. This preview supports review and practice; it does not issue certificates or automatically certify learning.')}</p><p>${T('英文界面可用；教材与任务单目前保留中文正本。个人内容仅在本机保存，没有云端同步。','The interface supports English; the canonical textbook and worksheets remain in Chinese. Personal work is local, with no cloud sync.')}</p><div class="actions">${link('identity',T('课程视觉基线','Course identity'),'secondary')}<a class="quiet-link" href="${repo}" target="_blank" rel="noopener">${T('参与课程共建','Course repository')}${icon('external',14)}</a></div></section></div>`;}
function glossaryCards(query){const q=query.trim().toLowerCase();const seen=new Set();const terms=data.glossary.filter(g=>{if(seen.has(g.term))return false;seen.add(g.term);return !q||(g.term+' '+g.meaning).toLowerCase().includes(q);});return terms.map(g=>`<article class="glossary-card"><h2>${esc(g.term)}</h2><p>${esc(g.meaning)}</p><a href="#/learn/${g.unit}?section=${g.section}">${T('回到','Back to ')}${labelOf(g.unit)}${icon('arrow',14)}</a></article>`).join('')||`<p>${T('未找到匹配术语，可尝试其他词。','No matching terms. Try another word.')}</p>`;}
function openDialog(title,body){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=body;$('#app-dialog').showModal();}
function download(name,body,type='text/plain;charset=utf-8'){const blob=new Blob([body],{type});const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function backupJSON(){return JSON.stringify({...state,courseVersion:data.version,sourceCommit:data.sourceCommit},null,2);}
function exportActivity(id){const a=definitions.find(x=>x.id===id),r=LearningCore.activity(state,id);download(id+'-'+(r.status==='complete'?'self-checked':'draft')+'.md',LearningCore.toMarkdown(a,r,fixed('activities/student/'+id+'.md')),'text/markdown;charset=utf-8');toast(T('已准备完整活动文件','Your full activity file is ready'));}
function previewActivity(id){const a=definitions.find(x=>x.id===id),r=LearningCore.activity(state,id);openDialog(T('完整产物与修订历史','Artifact & revision history'),`<p>${T('包含全部字段、缺项和已保留的修订快照。','Includes all fields, missing items and revision snapshots.')}</p><pre class="artifact-export">${esc(LearningCore.toMarkdown(a,r,fixed('activities/student/'+id+'.md')))}</pre><button class="btn primary" id="dialog-export">${T('导出 Markdown','Export Markdown')}</button>`);$('#dialog-export').onclick=()=>exportActivity(id);}
function prepareImport(raw){const imported=LearningCore.validate(JSON.parse(raw),definitions);pendingImport=imported;openDialog(T('确认合并这份备份','Review this import'),`<p>${T('将合并阅读标记、笔记和活动；同名笔记与活动以导入文件为准。导入前会保留一份本机备份，原活动草稿也会进入修订历史。','Read marks, notes and activities will be merged. Imported notes and activities replace matching entries. A local backup and previous activity snapshots are kept.')}</p><ul><li>${Object.keys(imported.notes).length} ${T('条笔记','notes')}</li><li>${Object.keys(imported.activities).length} ${T('项活动','activities')}</li><li>${Object.keys(imported.reading).length} ${T('个单元阅读记录','reading records')}</li></ul><button id="confirm-import" class="btn primary">${T('确认合并恢复','Confirm merge & restore')}</button>`);$('#confirm-import').onclick=()=>{const before=LearningCore.clone(state);let merged;try{merged=LearningCore.validate(LearningCore.merge(state,pendingImport),definitions);}catch{toast(T('合并后超出记录限制；现有记录未改变','Merged records exceed limits. Existing records are unchanged.'));return;}importBackup=before;try{localStorage.setItem(STORE+'.before-import',JSON.stringify(before));}catch{}state=merged;readError=false;persist();pendingImport=null;$('#app-dialog').close();location.hash='#/notebook';render(false);toast(T('已恢复；需要时可下载导入前的备份','Restored. You can download the previous backup.'));};}
function showTextBackup(){openDialog(T('文本备份与恢复','Text backup & restore'),`<p>${T('可复制保存下方内容；也可以粘贴本站备份，先验证，再确认合并。','Copy this text as a backup, or paste an existing backup to validate and review before merging.')}</p><label class="field" for="backup-text">JSON<textarea id="backup-text" rows="12" spellcheck="false">${esc(backupJSON())}</textarea></label><div class="actions"><button class="btn primary" id="copy-backup">${T('复制备份','Copy backup')}</button><button class="btn secondary" id="validate-backup">${T('验证并恢复','Validate & restore')}</button></div><p id="backup-error" role="alert"></p>`);$('#copy-backup').onclick=async()=>{try{await navigator.clipboard.writeText($('#backup-text').value);toast(T('备份已复制','Backup copied'));}catch{$('#backup-text').select();toast(T('请使用复制快捷键保存选中文本','Use your copy shortcut to save the selected text'));}};$('#validate-backup').onclick=()=>{const raw=$('#backup-text').value;try{if(raw.length>2000000)throw Error('size');prepareImport(raw);}catch{$('#backup-error').textContent=T('格式无效或超出限制；现有记录没有改变。','Invalid format or limit exceeded. Existing records are unchanged.');}};}
function paintRead(id){const r=getRead(id);$$('[data-mark]').forEach(b=>{const done=r.done.includes(b.dataset.mark);b.classList.toggle('marked',done);b.setAttribute('aria-pressed',String(done));b.innerHTML=icon('check',15)+T(done?'我已读过 · 撤销':'标记我已读过',done?'Read · undo':'Mark as read');});const p=$('.reading-progress');if(p)p.innerHTML=`<span>${actualDone(id).length} / ${data.units[id].sections.length} ${T('节已标记','sections marked')}</span><div><i style="width:${progress(id)}%"></i></div>`;$$('[data-section-link]').forEach(a=>{const i=data.units[id].sections.findIndex(s=>s.id===a.dataset.sectionLink);a.querySelector('span').textContent=r.done.includes(a.dataset.sectionLink)?'✓':String(i+1).padStart(2,'0');});}
function bindNote(id){$('#margin-note')?.addEventListener('input',e=>{const key=e.target.dataset.noteKey;state.notes[key]={text:e.target.value,version:data.units[id].version,digest:data.units[id].digest,updatedAt:new Date().toISOString()};persist();});$('#save-bookmark')?.addEventListener('click',e=>{const b=e.currentTarget;getRead(id).bookmark=b.dataset.section;getRead(id).updatedAt=new Date().toISOString();state.lastRoute='#/learn/'+id+'?section='+b.dataset.section;persist(false);});}
function selectNote(id,section,focus=false){
 if(!focus&&$('#app-dialog').open&&$('#dialog-content #margin-note'))return;
 currentSection=section;const mobile=focus&&(focusMode||matchMedia('(max-width:1200px)').matches);
 $('#reading-notes').innerHTML=mobile?'':notePanel(id,section);
 if(mobile){openDialog(T('记下一个想法','Leave a margin note'),notePanel(id,section));$('#app-dialog').addEventListener('close',()=>{if($('#reading-notes')){$('#reading-notes').innerHTML=notePanel(id,section);bindNote(id);}},{once:true});}
 bindNote(id);$$('[data-section-link]').forEach(a=>{if(a.dataset.sectionLink===section)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});
 if(focus){if(!mobile)$('#reading-notes').scrollIntoView({block:'nearest'});$('#margin-note').focus({preventScroll:true});}
}
function bindReader(id,params){const u=data.units[id];if(!u)return;bindNote(id);$('#chapter-switch').onchange=e=>location.hash='#/learn/'+e.target.value;$('#font-down').onclick=()=>{fontSize=Math.max(16,fontSize-2);prefs();render(false);};$('#font-up').onclick=()=>{fontSize=Math.min(22,fontSize+2);prefs();render(false);};$('#focus-mode').onclick=()=>{focusMode=!focusMode;render(false);};$$('[data-mark]').forEach(b=>b.onclick=()=>{const r=getRead(id),s=b.dataset.mark;r.done=r.done.includes(s)?r.done.filter(x=>x!==s):[...r.done,s];r.updatedAt=new Date().toISOString();persist();paintRead(id);});$$('[data-note]').forEach(b=>b.onclick=()=>selectNote(id,b.dataset.note,true));
 const target=params.get('section');if(target&&u.sections.some(s=>s.id===target))requestAnimationFrame(()=>document.getElementById(target)?.scrollIntoView({block:'start'}));
 requestAnimationFrame(()=>{if(observer)observer.disconnect();observer=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top)[0];if(!visible)return;const section=visible.target.dataset.readingSection;getRead(id).bookmark=section;state.lastRoute='#/learn/'+id+'?section='+section;persist();if(section!==currentSection&&document.activeElement?.id!=='margin-note')selectNote(id,section);},{rootMargin:'-100px 0px -65% 0px',threshold:0});$$('[data-reading-section]').forEach(el=>observer.observe(el));});
}
function bind(){
 $('#course-search')?.addEventListener('input',e=>{mapQuery=e.target.value;$('#catalog-results').innerHTML=catalogResults();});$$('[data-part]').forEach(b=>b.onclick=()=>{mapPart=Number(b.dataset.part);$$('[data-part]').forEach(x=>{const active=Number(x.dataset.part)===mapPart;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active));});$('#catalog-results').innerHTML=catalogResults();});
 $('#glossary-search')?.addEventListener('input',e=>$('#glossary-results').innerHTML=glossaryCards(e.target.value));
 $('#start-form')?.addEventListener('input',e=>{if(['product','question','contribution'].includes(e.target.name)){state.start[e.target.name]=e.target.value;persist();}});$('#start-form')?.addEventListener('submit',e=>{e.preventDefault();persist(false);});
 $$('[data-explore-index]').forEach(b=>b.onclick=()=>{const x=getExplore(b.dataset.exploreId);x.index=Number(b.dataset.exploreIndex);x.updatedAt=new Date().toISOString();persist();$$('[data-explore-index]').forEach(n=>{n.classList.toggle('selected',n===b);n.setAttribute('aria-pressed',String(n===b));});$('#exploration-detail').innerHTML=explorationDetail(b.dataset.exploreId,x.index);});
 const explorationForm=$('#exploration-form');if(explorationForm){const id=explorationForm.dataset.exploration;explorationForm.addEventListener('input',e=>{if(['decision','explanation','revision'].includes(e.target.name)){const x=getExplore(id);x[e.target.name]=e.target.value;x.updatedAt=new Date().toISOString();persist();}});explorationForm.addEventListener('submit',e=>{e.preventDefault();persist(false);});$('#reveal-explanation').onclick=()=>{const x=getExplore(id);if(!x.decision||!x.explanation.trim()){toast(T('请先选择一个判断，并写下自己的依据','Choose a judgment and add your reasoning first'));return;}$('#exploration-feedback').classList.remove('hidden');};}
 $$('[data-release]').forEach(b=>b.onclick=()=>{getExplore('releases').index=Number(b.dataset.release);persist();$$('[data-release]').forEach(n=>{n.classList.toggle('active',n===b);n.setAttribute('aria-pressed',String(n===b));});$('#release-content').innerHTML=releaseDetail(Number(b.dataset.release));});
 const form=$('#activity-form');if(form){const id=form.dataset.activity,a=definitions.find(x=>x.id===id),r=LearningCore.activity(state,id);form.onsubmit=e=>e.preventDefault();form.addEventListener('input',e=>{if(!LearningCore.fieldsOf(a).some(f=>f.id===e.target.name))return;r.fields[e.target.name]=e.target.value;r.updatedAt=new Date().toISOString();r.status='draft';persist();$('#artifact-preview').innerHTML=artifactPreview(a,r);$('#activity-count').textContent=`${LearningCore.fieldsOf(a).length-LearningCore.missing(a,r).length} / ${LearningCore.fieldsOf(a).length} ${T('项已填','fields filled')}`;});$('#snapshot-button').onclick=()=>{if(!Object.values(r.fields).some(v=>v.trim())){toast(T('先写下一点内容，再保留快照','Add some work before keeping a snapshot'));return;}LearningCore.snapshot(r,T('我的修订快照','My revision snapshot'));r.updatedAt=new Date().toISOString();persist(false);};$('#check-completion')?.addEventListener('click',()=>{const missing=LearningCore.missing(a,r);const box=$('#completion-feedback');if(missing.length){box.innerHTML=`<h3>${T('还可以补充这些内容','Fields you can still add')} · ${missing.length}</h3><p>${T('草稿已保存；不确定可以明确写“未知／待核查”。','Your draft is saved. You may explicitly record unknowns.')}</p><ul>${missing.map(f=>{const step=a.steps.findIndex(s=>s.fields.some(x=>x.id===f.id));return `<li><a href="#/activity/${id}?step=${step}">${esc((f.row?f.row+' · ':'')+f.label)}</a></li>`;}).join('')}</ul>`;}else{r.status='complete';LearningCore.snapshot(r,T('本人完成填写检查','Self-checked fields'));r.updatedAt=new Date().toISOString();persist();box.innerHTML=`<h3>${T('已记录你的填写确认','Your self-check is recorded')}</h3><p>${T('全部字段已有内容。下一步请检查证据、边界与修订，再提交给教师或同伴评审。此状态不表示教学验收。','All fields contain text. Review evidence, limits and revisions before sharing with a teacher or peer. This does not certify learning.')}</p>`;}box.scrollIntoView({block:'nearest'});});}
 $$('[data-export-activity]').forEach(b=>b.onclick=()=>exportActivity(b.dataset.exportActivity));$$('[data-preview-activity]').forEach(b=>b.onclick=()=>previewActivity(b.dataset.previewActivity));$$('[data-export="json"]').forEach(b=>b.onclick=()=>download('AIOS101-learning-backup.json',backupJSON(),'application/json'));
 $('#previous-backup')?.addEventListener('click',()=>download('AIOS101-before-import.json',JSON.stringify(importBackup,null,2),'application/json'));$('#text-backup')?.addEventListener('click',showTextBackup);$('#import-button')?.addEventListener('click',()=>$('#import-file').click());$('#print-notebook')?.addEventListener('click',()=>window.print());
 $('#clear-records')?.addEventListener('click',()=>{if(!confirm(T('确定清除本浏览器的新旧学习记录及导入前备份？建议先导出。','Clear current and legacy learning records and the pre-import backup on this device? Export first.')))return;state=LearningCore.empty();readError=false;try{localStorage.removeItem(OLD_STORE);localStorage.removeItem(STORE+'.before-import');localStorage.removeItem(STORE);}catch{}importBackup=null;persist();render(false);toast(T('本机学习记录已清除','Learning records cleared'));});
}
function setMenu(open){$('#nav').classList.toggle('open',open);$('#menu').setAttribute('aria-expanded',String(open));$('#menu').ariaLabel=T(open?'收起导航':'展开导航',open?'Close navigation':'Open navigation');}
function render(scroll=true){if(!data)return;if(observer){observer.disconnect();observer=null;}const raw=(location.hash||'#/').slice(2),[path,query='']=raw.split('?'),params=new URLSearchParams(query);let route=path;const aliases={preface:'learn/PREFACE',lab:'explore/system',review:'resources'};if(aliases[route]){location.replace('#/'+aliases[route]+(query?'?'+query:''));return;}shell();let content;if(route.startsWith('learn/')){const id=route.split('/')[1];content=reader(id,params);if(data.units[id])state.lastRoute='#/'+route+(query?'?'+query:'');}else if(route.startsWith('activity/')){content=activityPage(route.split('/')[1],params);const a=state.activities[route.split('/')[1]];if(a)state.lastRoute='#/'+route+'?step='+a.step;}else if(route.startsWith('explore/'))content=exploration(route.split('/')[1]);else{if(route==='map'&&params.has('part'))mapPart=Math.min(3,Math.max(-1,Number(params.get('part'))||0));content=({'':home,map:mapPage,workshop,notebook,resources,identity:identityPage}[route]||(()=>unavailable(route)))();}
 $('#main').innerHTML=(!storageOK?`<div class="storage-alert" role="status">${T('当前浏览器记录暂不可读取或保存。可继续使用并导出；已有存储不会被覆盖。','Existing storage could not be read or saved. Continue in this session and export. Existing data will not be overwritten.')}</div>`:'')+content;setMenu(false);bind();bindCourseIdentity();if(scroll)window.scrollTo(0,0);if(route.startsWith('learn/'))bindReader(route.split('/')[1],params);persist();document.title=`AIOS101 · ${route.startsWith('learn/')?labelOf(route.split('/')[1]):T('AI 开源通识 · 交互学习','AI & Open Source Literacy')} · X-lab`;
}
$('#lang').onclick=()=>{lang=lang==='zh'?'en':'zh';prefs();render(false);};$('#theme').onclick=()=>{theme=theme==='light'?'dark':'light';prefs();shell();};$('#menu').onclick=()=>setMenu(!$('#nav').classList.contains('open'));$('.skip-link').onclick=e=>{e.preventDefault();$('#main').focus();};$('#close-dialog').onclick=()=>$('#app-dialog').close();
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('size');prepareImport(await file.text());}catch{toast(T('备份格式无效或超过 2 MB。现有记录没有改变。','Invalid backup or larger than 2 MB. Existing records are unchanged.'));}finally{e.target.value='';}};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#nav').classList.contains('open')){setMenu(false);$('#menu').focus();}});
window.addEventListener('hashchange',()=>{render();$('#main').focus({preventScroll:true});});
fetch('content.json').then(r=>{if(!r.ok)throw Error(r.status);return r.json();}).then(c=>{data=c;render();}).catch(()=>{$('#main').innerHTML=`<div class="wrap empty-state"><h1>${T('教材暂未载入','The textbook did not load')}</h1><p>${T('刷新重试，或先在仓库阅读。','Reload, or read the canonical materials in the repository.')}</p><a class="btn primary" href="${repo}/tree/main/textbook">${T('打开教材','Open textbook')}${icon('external')}</a></div>`;shell();});
